    }
    existing.count = existing.count + 1;
    existing.min = Math.min(existing.min, reading.millivolts);
    existing.max = Math.max(existing.max, reading.millivolts);
    if (severityRank(labels[index]) > severityRank(existing.worst)) {
      existing.worst = labels[index];
    }
  }
  return channels;
}

function buildReport(readingCount: number, channelCount: number, alertCount: number, labels: string[]): string {
  let worst = "standby";
  let worstRank = severityRank(worst);
  for (const label of labels) {
    const rank = severityRank(label);
    if (rank > worstRank) {
      worstRank = rank;
      worst = label;
    }
  }
