function eq(a:any,b:any,m:string){ if(JSON.stringify(a)!==JSON.stringify(b)){fails++; console.log("FAIL",m,"\n got ",JSON.stringify(a),"\n want",JSON.stringify(b));} }

// exhaustive classifySignal over a range
for(let v=-1000;v<=2000;v++) eq(New.classifySignal(v), Orig.classifySignal(v), "classify "+v);

// random batches
