  const n=Math.floor(r()*5); const arr:any[]=[];
  for(let i=0;i<n;i++){
    const kind=bads[Math.floor(r()*bads.length)];
    if(kind==="malformed"){arr.push(null);continue;}
    let rec:any={};
    if(kind!=="badchan")rec.channel=channels[Math.floor(r()*channels.length)]; else rec.channel="";
    if(kind!=="badunit")rec.unit=units[Math.floor(r()*units.length)]; else rec.unit="X";
    if(kind!=="badvalue")rec.value=Math.floor(r()*2000); else rec.value=1.5;
    rec.at=Math.floor(r()*10)-2;
    arr.push(rec);
  }
  const raw=(r()>0.1)?{readings:arr}:(r()>0.5?{readings:"x"}:null);
  const a=New.processBatch(raw as any), b=Orig.processBatch(raw as any);
  eq(a,b,"batch iter"+iter);
}
// too large
const many={readings:Array.from({length:501},(_,i)=>({channel:"A",unit:"V",value:1,at:i}))};
eq(New.processBatch(many as any),Orig.processBatch(many as any),"toolarge");
console.log(fails===0?"ALL MATCH":fails+" mismatches");
EOF
